export function wildEventReviewFixture(type,{sketch=false,challenge=false,reserveId='one'}={}){const doc={coins:99,adventure:{safe:true}},state=ensureClassicState(doc),lead=makeReferenceMon(151,90,{boxId:'lead',moves:['Tackle']}),fighter=makeReferenceMon(7,80,{boxId:'fighter',moves:['Tackle']}),reserve=sketch?makeReferenceMon(235,50,{boxId:reserveId,moves:['Tackle','Sketch','몸통박치기'],rogueSketchRule:'source-v1',rogueSketchPP:[2,1,17]}):makeReferenceMon(1,50,{boxId:reserveId,moves:['Tackle','몸통박치기','Growl'],pp:{tackle:3,growl:5},roguePPUps:{tackle:2}}),enemy=makeReferenceMon(7,20,{boxId:'event-enemy',moves:['Tackle']}),run={id:'wild-event-review',seed:'wild-event-review',rng:42,wave:22,biome:4,screen:'mystery',mysteryRule:'part-timer-v10',berryCoreRule:'source-v1',berryFullRule:'source-v1',party:[lead,fighter,reserve],modifiers:[],tools:{},balls:{masterball:1},money:1000,rerolls:0,encounter:{kind:'mystery',key:type},mystery:{type,stage:'choose',enemy},participants:[],awardedFoes:[],expNotices:[],pendingMoves:[],rewards:[]};if(challenge){run.challenges=[{id:0,value:1},{id:5,value:1}];run.challengeEligibilityRule='source-subset-v1';}if(type==='dark-deal'){run.wave=101;run.money=5000;run.balls.rogueball=0;run.formItems={};run.mysteryState={spawnWeight:3,history:[]};}if(type==='bug-superfan'){run.wave=42;run.party[0]=makeReferenceMon(151,100,{boxId:'lead',moves:['Ice Beam']});run.party[1]=makeReferenceMon(10,40,{boxId:'fighter',moves:['Tackle']});}if(type==='mysterious-chest'){for(let i=1;i<100000;i++){const seed=Math.imul(i,1234567)>>>0;if(Math.floor(classicRandom({rng:seed})*100)<30){run.rng=seed;break;}}}if(type==='uncommon-breed')enemy.rogueMysteryEggMove='Tackle';if(type==='berries'){enemy.rogueBoss=true;enemy.rogueBossSegments=2;}if(type==='fight-or-flight'){enemy.rogueBoss=true;enemy.rogueBossSegments=2;run.mystery.reward=drawClassicFightReward(run);}state.slots[0]=run;state.slots[1]={id:'other',safe:true};applyClassicAction(doc,{action:'mysterySelect',job:type==='mysterious-chest'?'open':type==='dark-deal'?'deal':'battle'});applyClassicAction(doc,{action:'mysteryConfirm'});while(run.initialSwitchSlots?.length)applyClassicAction(doc,{action:'initialSwitch',slot:run.initialSwitchSlots[0]});return doc;}
